record UserResponse(Long id, String displayName) {}

@GetMapping("/users/{id}")
ResponseEntity<UserResponse> getUser(@PathVariable Long id) {
    User entity = userRepository.findById(id).orElseThrow();
    return ResponseEntity.ok(new UserResponse(entity.getId(), entity.getDisplayName()));
    // passwordHash et autres colonnes internes ne quittent jamais cette méthode
}

